304	  /** List all imported documents. */
305	  listDocuments(): Document[] {
306	    const docs = this.persistence.readJson<Document[]>(DOCUMENTS_META);
307	    logger.debug(SERVICE, 'Listing documents', { count: docs?.length ?? 0 });
308	    return docs ?? [];
