311	  /** Import a file from the given path. */
312	  importDocument(filePath: string): Document {
313	    if (!fs.existsSync(filePath)) {
314	      logger.error(SERVICE, `File not found: ${filePath}`);
315	      throw new Error(`File not found: ${filePath}`);
316	    }
317	
318	    const filename = path.basename(filePath);
319	    const content = fs.readFileSync(filePath, 'utf-8');
320	    const stats = fs.statSync(filePath);
321	
322	    const doc: Document = {
323	      id: uuidv4(),
324	      title: filename.replace(/\.[^.]+$/, ''),
325	      filename,
326	      importedAt: new Date().toISOString(),
327	      size: stats.size,
328	      status: 'imported',
329	    };
330	
331	    // Copy file to data directory
332	    this.persistence.copyFileToDocuments(filePath, filename);
333	
334	    // Store content for indexing
335	    this.persistence.writeText(`content/${doc.id}.txt`, content);
336	
337	    // Update metadata
338	    const docs = this.listDocuments();
339	    docs.push(doc);
340	    this.persistence.writeJson(DOCUMENTS_META, docs);
341	
342	    logger.info(SERVICE, 'Document imported', {
343	      documentId: doc.id,
344	      filename: doc.filename,
345	      size: doc.size,
346	    });
347	    return doc;
348	  }
