357	  getDocumentContent(id: string): string | null {
358	    return this.persistence.readText(`content/${id}.txt`);
359	  }
360	
361	  /** Update a document's metadata. */
362	  updateDocument(id: string, updates: Partial<Document>): Document | null {
363	    const docs = this.listDocuments();
364	    const index = docs.findIndex(d => d.id === id);
365	    if (index === -1) return null;
366	
367	    docs[index] = { ...docs[index], ...updates };
368	    this.persistence.writeJson(DOCUMENTS_META, docs);
369	    logger.info(SERVICE, 'Document updated', { documentId: id, fields: Object.keys(updates) });
370	    return docs[index];
371	  }
