373	  /** Delete a document by ID. */
374	  deleteDocument(id: string): boolean {
375	    const docs = this.listDocuments();
376	    const doc = docs.find(d => d.id === id);
377	    if (!doc) return false;
378	
379	    this.persistence.deleteFromDocuments(doc.filename);
380	
381	    const updated = docs.filter(d => d.id !== id);
382	    this.persistence.writeJson(DOCUMENTS_META, updated);
383	    logger.info(SERVICE, 'Document deleted', { documentId: id, filename: doc.filename });
384	    return true;
