404	export class IndexingService {
405	  private persistence: PersistenceService;
406	
407	  constructor(persistence: PersistenceService) {
408	    this.persistence = persistence;
409	  }
410	
411	  /** Start indexing documents. If documentId is provided, index only that document. */
412	  async startIndexing(documentId?: string): Promise<IndexStatus> {
413	    const status = this.getStatus();
414	
415	    if (documentId) {
416	      const content = this.persistence.readText(`content/${documentId}.txt`);
417	      if (!content) {
418	        logger.error(SERVICE, `Content not found for document: ${documentId}`);
419	        return { ...status, status: 'error' };
420	      }
421	      const chunks = this.chunkDocument(documentId, content);
422	      this.persistence.writeJson(`${CHUNKS_DIR}/${documentId}.json`, chunks);
423	      logger.info(SERVICE, 'Single document indexed', {
424	        documentId,
425	        chunkCount: chunks.length,
426	      });
427	      return this.getStatus();
428	    }
429	
430	    const docsMeta = this.persistence.readJson<Document[]>('documents-meta.json') ?? [];
431	    const chunksMeta = this.persistence.readJson<Record<string, string[]>>(INDEX_META) ?? {};
432	
433	    let indexedCount = 0;
434	    for (const doc of docsMeta) {
435	      if (chunksMeta[doc.id]) continue;
436	
437	      const content = this.persistence.readText(`content/${doc.id}.txt`);
438	      if (!content) continue;
439	
440	      const chunks = this.chunkDocument(doc.id, content);
441	      this.persistence.writeJson(`${CHUNKS_DIR}/${doc.id}.json`, chunks);
442	      chunksMeta[doc.id] = chunks.map(c => c.id);
443	      indexedCount++;
444	      logger.info(SERVICE, 'Document indexed', {
445	        documentId: doc.id,
446	        chunkCount: chunks.length,
447	      });
448	    }
449	
450	    this.persistence.writeJson(INDEX_META, chunksMeta);
451	    logger.info(SERVICE, 'Batch indexing complete', {
452	      totalDocs: docsMeta.length,
453	      newlyIndexed: indexedCount,
454	    });
455	    return this.getStatus();
456	  }
457	
458	  /** Get current indexing status. */
459	  getStatus(): IndexStatus {
460	    const docs = this.persistence.readJson<Document[]>('documents-meta.json') ?? [];
461	    const chunksMeta = this.persistence.readJson<Record<string, string[]>>(INDEX_META) ?? {};
462	
463	    const currentIndexed = Object.keys(chunksMeta).length;
464	    const totalDocuments = docs.length;
465	    const isReady = currentIndexed === totalDocuments && totalDocuments > 0;
466	
467	    return {
468	      status: isReady ? 'ready' : currentIndexed > 0 ? 'indexing' : 'idle',
469	      currentIndexed,
470	      totalDocuments,
471	      lastIndexed: new Date().toISOString(),
472	    };
473	  }
474	
475	  /** Get all chunks for a document. */
476	  getChunksForDocument(documentId: string): Chunk[] {
477	    return this.persistence.readJson<Chunk[]>(`${CHUNKS_DIR}/${documentId}.json`) ?? [];
478	  }
479	
480	  /** Get all chunks across all documents. */
481	  getAllChunks(): Chunk[] {
482	    const chunksMeta = this.persistence.readJson<Record<string, string[]>>(INDEX_META) ?? {};
483	    const allChunks: Chunk[] = [];
484	
485	    for (const docId of Object.keys(chunksMeta)) {
486	      const chunks = this.getChunksForDocument(docId);
487	      allChunks.push(...chunks);
488	    }
489	
490	    return allChunks;
491	  }
492	
493	  /** Split a document into chunks of ~500 characters at paragraph boundaries. */
494	  private chunkDocument(documentId: string, content: string): Chunk[] {
495	    const CHUNK_SIZE = 500;
496	    const chunks: Chunk[] = [];
497	
498	    const paragraphs = content.split(/\n\s*\n/).filter(p => p.trim().length > 0);
499	
500	    let buffer = '';
501	    let chunkIndex = 0;
502	
503	    for (const para of paragraphs) {
504	      if (buffer.length + para.length > CHUNK_SIZE && buffer.length > 0) {
505	        chunks.push(this.createChunk(documentId, chunkIndex++, buffer.trim()));
506	        buffer = para;
507	      } else {
508	        buffer += (buffer ? '\n\n' : '') + para;
509	      }
510	    }
511	
512	    if (buffer.trim()) {
513	      chunks.push(this.createChunk(documentId, chunkIndex, buffer.trim()));
514	    }
515	
516	    return chunks;
517	  }
518	
519	  private createChunk(documentId: string, index: number, content: string): Chunk {
520	    return {
521	      id: uuidv4(),
522	      documentId,
523	      content,
524	      index,
525	      metadata: {
526	        charCount: String(content.length),
527	        wordCount: String(content.split(/\s+/).length),
528	      },
529	    };
