533	/**
534	 * Structured logging module for the Knowledge Base application.
535	 *
536	 * Provides log levels, timestamps, and structured JSON output for
537	 * all services. Replaces raw console.log calls with consistent,
538	 * machine-parseable log entries.
539	 */
540	
541	export enum LogLevel {
542	  DEBUG = 'DEBUG',
543	  INFO = 'INFO',
544	  WARN = 'WARN',
545	  ERROR = 'ERROR',
546	}
547	
548	interface LogEntry {
549	  timestamp: string;
550	  level: LogLevel;
551	  service: string;
552	  message: string;
553	  data?: Record<string, unknown>;
554	}
