556	class Logger {
557	  private minLevel: LogLevel;
558	  private static readonly LEVEL_ORDER: LogLevel[] = [
559	    LogLevel.DEBUG,
560	    LogLevel.INFO,
561	    LogLevel.WARN,
562	    LogLevel.ERROR,
563	  ];
564	
565	  constructor(minLevel: LogLevel = LogLevel.DEBUG) {
566	    this.minLevel = minLevel;
567	  }
568	
569	  private shouldLog(level: LogLevel): boolean {
570	    const minIdx = Logger.LEVEL_ORDER.indexOf(this.minLevel);
571	    const levelIdx = Logger.LEVEL_ORDER.indexOf(level);
572	    return levelIdx >= minIdx;
573	  }
574	
575	  private emit(entry: LogEntry): void {
576	    const output = JSON.stringify(entry);
577	    switch (entry.level) {
578	      case LogLevel.ERROR:
579	        console.error(output);
580	        break;
581	      case LogLevel.WARN:
582	        console.warn(output);
583	        break;
584	      default:
585	        console.log(output);
586	        break;
587	    }
588	  }
589	
590	  private log(level: LogLevel, service: string, message: string, data?: Record<string, unknown>): void {
591	    if (!this.shouldLog(level)) return;
592	
593	    const entry: LogEntry = {
594	      timestamp: new Date().toISOString(),
595	      level,
596	      service,
597	      message,
598	    };
599	
600	    if (data && Object.keys(data).length > 0) {
601	      entry.data = data;
602	    }
603	
604	    this.emit(entry);
605	  }
606	
607	  debug(service: string, message: string, data?: Record<string, unknown>): void {
608	    this.log(LogLevel.DEBUG, service, message, data);
609	  }
