import { useEffect, useRef, useState } from 'react';
import { Citation, FeedbackRating, QAHistory, QAResponse } from '../../shared/types';

interface Props {
  history: QAHistory[];
  feedback: Record<string, FeedbackRating>;
  pendingQuestion: string | null;
  error: string | null;
  onRate: (answerId: string, rating: FeedbackRating) => void;
}

/** Full Q&A history rendered as a chat-style conversation. */
export function ConversationHistory({ history, feedback, pendingQuestion, error, onRate }: Props) {
  const endRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    endRef.current?.scrollIntoView?.({ block: 'end' });
  }, [history.length, pendingQuestion, error]);

  if (history.length === 0 && !pendingQuestion && !error) {
    return (
      <div style={{ color: '#666', textAlign: 'center', paddingTop: '40px' }}>
        No conversation yet. Ask a question about your documents to get started.
      </div>
    );
  }

  return (
    <div role="log" aria-label="Conversation history" style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
      {history.map((item, index) => (
        <div key={item.response.id ?? index} style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          <UserBubble text={item.question} />
          <AnswerBubble
            response={item.response}
            rating={item.response.id ? feedback[item.response.id] : undefined}
            onRate={onRate}
          />
        </div>
      ))}
      {pendingQuestion && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          <UserBubble text={pendingQuestion} />
          <div role="status" style={{ ...bubbleBase, alignSelf: 'flex-start', color: '#8888bb', fontStyle: 'italic' }}>
            Thinking…
          </div>
        </div>
      )}
      {error && (
        <div role="alert" style={{ ...bubbleBase, alignSelf: 'flex-start', border: '1px solid #d9534f', color: '#f0a0a0' }}>
          {error}
        </div>
      )}
      <div ref={endRef} />
    </div>
  );
}

const bubbleBase: React.CSSProperties = {
  maxWidth: '80%',
  padding: '10px 14px',
  borderRadius: '10px',
  fontSize: '14px',
  lineHeight: 1.55,
  whiteSpace: 'pre-wrap',
  wordBreak: 'break-word',
};

function UserBubble({ text }: { text: string }) {
  return (
    <div
      aria-label="Question"
      style={{ ...bubbleBase, alignSelf: 'flex-end', background: '#533483', color: '#fff', borderBottomRightRadius: '2px' }}
    >
      {text}
    </div>
  );
}

interface AnswerProps {
  response: QAResponse;
  rating: FeedbackRating | undefined;
  onRate: (answerId: string, rating: FeedbackRating) => void;
}

function AnswerBubble({ response, rating, onRate }: AnswerProps) {
  return (
    <article
      aria-label="Answer"
      data-answer-id={response.id}
      style={{
        ...bubbleBase,
        alignSelf: 'flex-start',
        background: '#1a1a3e',
        border: '1px solid #0f3460',
        borderBottomLeftRadius: '2px',
        whiteSpace: 'normal',
      }}
    >
      <div style={{ whiteSpace: 'pre-wrap' }}>{response.answer}</div>

      {response.citations.length > 0 && (
        <div style={{ marginTop: '10px' }}>
          <div style={{ fontSize: '11px', fontWeight: 600, color: '#8888bb', marginBottom: '4px' }}>
            Citations ({response.citations.length})
          </div>
          {response.citations.map((c, i) => (
            <CitationItem key={`${c.documentId}-${c.chunkIndex}-${i}`} citation={c} number={i + 1} />
          ))}
        </div>
      )}

      <div style={{ marginTop: '10px', display: 'flex', alignItems: 'center', gap: '12px', flexWrap: 'wrap' }}>
        <ConfidenceIndicator confidence={response.confidence} />
        <span style={{ fontSize: '10px', color: '#666' }}>
          {new Date(response.timestamp).toLocaleString()}
        </span>
        {response.id && (
          <span style={{ marginLeft: 'auto', display: 'flex', gap: '4px' }}>
            <FeedbackButton
              label="Mark answer helpful"
              symbol="👍"
              active={rating === 'up'}
              onClick={() => onRate(response.id, 'up')}
            />
            <FeedbackButton
              label="Mark answer not helpful"
              symbol="👎"
              active={rating === 'down'}
              onClick={() => onRate(response.id, 'down')}
            />
          </span>
        )}
      </div>
    </article>
  );
}

function CitationItem({ citation, number }: { citation: Citation; number: number }) {
  const [open, setOpen] = useState(false);
  return (
    <div style={{ marginTop: '4px', borderLeft: '2px solid #533483', paddingLeft: '8px' }}>
      <button
        type="button"
        aria-expanded={open}
        onClick={() => setOpen(o => !o)}
        style={{
          background: 'none',
          border: 'none',
          color: '#b088f9',
          cursor: 'pointer',
          fontSize: '12px',
          padding: 0,
          textAlign: 'left',
        }}
      >
        {open ? '▾' : '▸'} [{number}] {citation.documentTitle} (chunk {citation.chunkIndex})
      </button>
      {open && (
        <blockquote
          style={{
            margin: '4px 0 2px',
            fontSize: '12px',
            color: '#c0c0d8',
            background: '#14142e',
            padding: '6px 8px',
            borderRadius: '4px',
            whiteSpace: 'pre-wrap',
          }}
        >
          {citation.excerpt}
        </blockquote>
      )}
    </div>
  );
}

function ConfidenceIndicator({ confidence }: { confidence: number }) {
  const pct = Math.round(Math.max(0, Math.min(1, confidence)) * 100);
  const level = pct >= 70 ? 'High' : pct >= 40 ? 'Medium' : 'Low';
  const color = pct >= 70 ? '#5cb85c' : pct >= 40 ? '#f0ad4e' : '#d9534f';
  return (
    <span
      role="meter"
      aria-label="Confidence"
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={pct}
      aria-valuetext={`${level} confidence, ${pct}%`}
      title={`${level} confidence`}
      style={{ display: 'inline-flex', alignItems: 'center', gap: '6px', fontSize: '11px', color: '#aaa' }}
    >
      <span style={{ width: '60px', height: '6px', background: '#2a2a4e', borderRadius: '3px', overflow: 'hidden' }}>
        <span style={{ display: 'block', width: `${pct}%`, height: '100%', background: color }} />
      </span>
      {level} confidence ({pct}%)
    </span>
  );
}

interface FeedbackButtonProps {
  label: string;
  symbol: string;
  active: boolean;
  onClick: () => void;
}

function FeedbackButton({ label, symbol, active, onClick }: FeedbackButtonProps) {
  return (
    <button
      type="button"
      aria-label={label}
      aria-pressed={active}
      title={label}
      onClick={onClick}
      style={{
        padding: '2px 8px',
        background: active ? '#533483' : 'transparent',
        border: `1px solid ${active ? '#b088f9' : '#0f3460'}`,
        borderRadius: '4px',
        cursor: 'pointer',
        fontSize: '13px',
      }}
    >
      {symbol}
    </button>
  );
}

