}

function ConfidenceIndicator({ confidence }: { confidence: number }) {
  const pct = Math.round(Math.max(0, Math.min(1, confidence)) * 100);
  const level = pct >= 70 ? 'High' : pct >= 40 ? 'Medium' : 'Low';
