import { useState } from 'react';
import { FeedbackRating, QAHistory } from '../../shared/types';
import { ConversationHistory } from './ConversationHistory';

interface Props {
  history: QAHistory[];
  feedback: Record<string, FeedbackRating>;
  pendingQuestion: string | null;
  error: string | null;
  onAsk: (question: string) => void;
  onRate: (answerId: string, rating: FeedbackRating) => void;
  onClearHistory: () => void;
}

export function QuestionPanel({ history, feedback, pendingQuestion, error, onAsk, onRate, onClearHistory }: Props) {
  const [question, setQuestion] = useState('');
  const busy = pendingQuestion !== null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!question.trim() || busy) return;
    onAsk(question.trim());
    setQuestion('');
  };

  return (
    <section aria-label="Questions" style={{ flex: 1, display: 'flex', flexDirection: 'column', minHeight: 0 }}>
      <div style={{
        padding: '8px 20px',
        borderBottom: '1px solid #0f3460',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
      }}>
        <h3 style={{ fontSize: '13px', fontWeight: 500, color: '#a0a0c0' }}>
          Conversation ({history.length})
        </h3>
        {history.length > 0 && (
          <button
            type="button"
            onClick={onClearHistory}
            disabled={busy}
            style={{
              padding: '3px 10px',
              background: 'transparent',
              color: '#a0a0c0',
              border: '1px solid #0f3460',
              borderRadius: '3px',
              cursor: 'pointer',
              fontSize: '11px',
            }}
          >
            Clear history
          </button>
        )}
      </div>

      <div style={{ flex: 1, overflow: 'auto', padding: '16px 20px' }}>
        <ConversationHistory
          history={history}
          feedback={feedback}
          pendingQuestion={pendingQuestion}
          error={error}
          onRate={onRate}
        />
      </div>

      <form
        onSubmit={handleSubmit}
        style={{
          display: 'flex',
          padding: '12px 20px',
          borderTop: '1px solid #0f3460',
          background: '#16213e',
        }}
      >
        <input
          type="text"
          aria-label="Question"
          value={question}
          onChange={e => setQuestion(e.target.value)}
          placeholder="Ask a question about your documents..."
          style={{
            flex: 1,
            padding: '10px 14px',
            background: '#1a1a2e',
            color: '#e0e0e0',
            border: '1px solid #0f3460',
            borderRadius: '6px',
            fontSize: '14px',
            outline: 'none',
          }}
        />
        <button
          type="submit"
          disabled={busy}
          style={{
            marginLeft: '10px',
            padding: '10px 20px',
            background: busy ? '#3a2a5e' : '#533483',
            color: '#fff',
            border: 'none',
            borderRadius: '6px',
            cursor: busy ? 'default' : 'pointer',
            fontSize: '14px',
            fontWeight: 500,
          }}
        >
          {busy ? 'Asking…' : 'Ask'}
        </button>
      </form>
    </section>
  );
}

