import { useState, useCallback, useEffect } from 'react';
import { DocumentList } from './components/DocumentList';
import { QuestionPanel } from './components/QuestionPanel';
import { DocumentDetail } from './components/DocumentDetail';
import { ResetDialog } from './components/ResetDialog';
import { StatusBar } from './components/StatusBar';
import { Document, AppStatus, FeedbackRating, IndexStatus, QAHistory } from '../shared/types';

const EMPTY_STATUS: AppStatus = { documentsLoaded: 0, indexStatus: 'idle', lastActivity: '' };

function toAppStatus(status: IndexStatus): AppStatus {
  return {
    documentsLoaded: status.totalDocuments,
    indexStatus: status.status,
    lastActivity: status.lastIndexed ?? '',
  };
}

function errorMessage(err: unknown): string {
  return err instanceof Error ? err.message : String(err);
}

const headerButton: React.CSSProperties = {
  padding: '6px 14px',
  background: '#0f3460',
  color: '#e0e0e0',
  border: '1px solid #1a1a4e',
  borderRadius: '4px',
  cursor: 'pointer',
  fontSize: '13px',
};

export function App() {
  const [documents, setDocuments] = useState<Document[]>([]);
  const [selectedDoc, setSelectedDoc] = useState<Document | null>(null);
  const [appStatus, setAppStatus] = useState<AppStatus>(EMPTY_STATUS);
  const [history, setHistory] = useState<QAHistory[]>([]);
  const [feedback, setFeedback] = useState<Record<string, FeedbackRating>>({});
  const [pendingQuestion, setPendingQuestion] = useState<string | null>(null);
  const [qaError, setQaError] = useState<string | null>(null);
  const [confirmingReset, setConfirmingReset] = useState(false);
  const [resetting, setResetting] = useState(false);

  const refreshDocuments = useCallback(async () => {
    try {
      const [docs, status] = await Promise.all([
        window.knowledgeBase.documents.list(),
        window.knowledgeBase.indexing.status(),
      ]);
      setDocuments(docs);
      setAppStatus(toAppStatus(status));
      setSelectedDoc(current => (current ? docs.find(d => d.id === current.id) ?? null : null));
    } catch (err) {
      console.error('Failed to refresh documents:', err);
    }
  }, []);

  const refreshConversation = useCallback(async () => {
    try {
      const [items, entries] = await Promise.all([
        window.knowledgeBase.qa.history(),
        window.knowledgeBase.feedback.list(),
      ]);
      setHistory(items);
      const map: Record<string, FeedbackRating> = {};
      for (const e of entries) map[e.answerId] = e.rating;
      setFeedback(map);
    } catch (err) {
      console.error('Failed to load conversation:', err);
    }
  }, []);

  const refreshAll = useCallback(async () => {
    await Promise.all([refreshDocuments(), refreshConversation()]);
  }, [refreshDocuments, refreshConversation]);

  useEffect(() => {
    refreshAll();
  }, [refreshAll]);

  const handleImport = useCallback(async () => {
    console.log('Import triggered - use window.knowledgeBase.documents.import(filePath)');
  }, []);

  const handleAskQuestion = useCallback(async (question: string) => {
    setQaError(null);
    setPendingQuestion(question);
    try {
      const response = await window.knowledgeBase.qa.ask(question);
      setHistory(prev => [...prev, { question, response }]);
      const status = await window.knowledgeBase.indexing.status();
      setAppStatus(toAppStatus(status));
    } catch (err) {
      console.error('Q&A failed:', err);
      setQaError(`Could not answer the question: ${errorMessage(err)}`);
    } finally {
      setPendingQuestion(null);
    }
  }, []);

  const handleRate = useCallback(async (answerId: string, rating: FeedbackRating) => {
    try {
      const entry = await window.knowledgeBase.feedback.submit(answerId, rating);
      setFeedback(prev => ({ ...prev, [entry.answerId]: entry.rating }));
    } catch (err) {
      console.error('Feedback failed:', err);
    }
  }, []);

  const handleClearHistory = useCallback(async () => {
    try {
      await window.knowledgeBase.qa.clearHistory();
      setHistory([]);
      setQaError(null);
    } catch (err) {
      console.error('Clear history failed:', err);
    }
  }, []);

  const handleReset = useCallback(async () => {
    setResetting(true);
    try {
      await window.knowledgeBase.app.reset();
      setSelectedDoc(null);
      setQaError(null);
      await refreshAll();
      setConfirmingReset(false);
    } catch (err) {
      console.error('Reset failed:', err);
    } finally {
      setResetting(false);
    }
  }, [refreshAll]);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
      <header style={{
        padding: '12px 20px',
        background: '#16213e',
        borderBottom: '1px solid #0f3460',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
      }}>
        <h1 style={{ fontSize: '18px', fontWeight: 600 }}>Knowledge Base</h1>
        <div style={{ display: 'flex', gap: '8px' }}>
          <button type="button" onClick={refreshAll} style={headerButton}>
            Refresh
          </button>
          <button
            type="button"
            aria-label="Reset all data"
            aria-haspopup="dialog"
            onClick={() => setConfirmingReset(true)}
            disabled={pendingQuestion !== null}
            style={{ ...headerButton, background: '#5a1f2a', border: '1px solid #d9534f' }}
          >
            Reset
          </button>
        </div>
      </header>

      <div style={{ display: 'flex', flex: 1, overflow: 'hidden' }}>
        {/* Left panel: Document list */}
        <div style={{
          width: '280px',
          borderRight: '1px solid #0f3460',
          display: 'flex',
          flexDirection: 'column',
          background: '#16213e',
        }}>
          <div style={{
            padding: '10px 16px',
            borderBottom: '1px solid #0f3460',
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
          }}>
            <span style={{ fontSize: '13px', fontWeight: 500, color: '#a0a0c0' }}>
              Documents ({documents.length})
            </span>
            <button
              type="button"
              onClick={handleImport}
              style={{
                padding: '4px 10px',
                background: '#533483',
                color: '#fff',
                border: 'none',
                borderRadius: '3px',
                cursor: 'pointer',
                fontSize: '12px',
              }}
            >
              + Import
            </button>
          </div>
          <DocumentList
            documents={documents}
            onSelect={setSelectedDoc}
            selectedId={selectedDoc?.id ?? null}
          />
        </div>

        {/* Right panel: optional document detail above the conversation */}
        <div style={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
          {selectedDoc && (
            <div style={{
              maxHeight: '40%',
              overflow: 'auto',
              padding: '16px 20px',
              borderBottom: '1px solid #0f3460',
              position: 'relative',
            }}>
              <button
                type="button"
                aria-label="Close document"
                onClick={() => setSelectedDoc(null)}
                style={{
                  position: 'absolute',
                  top: '10px',
                  right: '14px',
                  background: 'none',
                  border: 'none',
                  color: '#888',
                  cursor: 'pointer',
                  fontSize: '16px',
                }}
              >
                ×
              </button>
              <DocumentDetail document={selectedDoc} />
            </div>
          )}

          <QuestionPanel
            history={history}
            feedback={feedback}
            pendingQuestion={pendingQuestion}
            error={qaError}
            onAsk={handleAskQuestion}
            onRate={handleRate}
            onClearHistory={handleClearHistory}
          />
        </div>
      </div>

      <StatusBar status={appStatus} />

      {confirmingReset && (
        <ResetDialog
          busy={resetting}
          onCancel={() => setConfirmingReset(false)}
          onConfirm={handleReset}
        />
      )}
    </div>
  );
}

