import { useEffect, useRef } from 'react';

interface Props {
  busy: boolean;
  onCancel: () => void;
  onConfirm: () => void;
}

/** In-app confirmation dialog shown before wiping all data. */
export function ResetDialog({ busy, onCancel, onConfirm }: Props) {
  const cancelRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    cancelRef.current?.focus();
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && !busy) onCancel();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [busy, onCancel]);

  return (
    <div
      style={{
        position: 'fixed',
        inset: 0,
        background: 'rgba(0, 0, 0, 0.6)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        zIndex: 100,
      }}
    >
      <div
        role="alertdialog"
        aria-modal="true"
        aria-labelledby="reset-dialog-title"
        aria-describedby="reset-dialog-desc"
        style={{
          width: '420px',
          maxWidth: '90vw',
          padding: '20px',
          background: '#16213e',
          border: '1px solid #d9534f',
          borderRadius: '8px',
        }}
      >
        <h2 id="reset-dialog-title" style={{ fontSize: '16px', marginBottom: '10px' }}>
          Delete all data?
        </h2>
        <p id="reset-dialog-desc" style={{ fontSize: '13px', color: '#c0c0d8', lineHeight: 1.5 }}>
          This permanently deletes all documents, chunks, Q&amp;A history and feedback.
          It cannot be undone.
        </p>
        <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '8px', marginTop: '18px' }}>
          <button
            ref={cancelRef}
            type="button"
            onClick={onCancel}
            disabled={busy}
            style={{
              padding: '6px 14px',
              background: '#0f3460',
              color: '#e0e0e0',
              border: '1px solid #1a1a4e',
              borderRadius: '4px',
              cursor: 'pointer',
              fontSize: '13px',
            }}
          >
            Cancel
          </button>
          <button
            type="button"
            onClick={onConfirm}
            disabled={busy}
            style={{
              padding: '6px 14px',
              background: '#d9534f',
              color: '#fff',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer',
              fontSize: '13px',
            }}
          >
            {busy ? 'Deleting…' : 'Delete everything'}
          </button>
        </div>
      </div>
    </div>
  );
}

